class Solution:
    def subsequencesWithMiddleMode(self, nums: List[int]) -> int:
        from itertools import combinations
        from collections import Counter
        MOD = 10**9 + 7
        ans = 0
        for c in combinations(range(len(nums)), 5):
            v = [nums[i] for i in c]
            cnt = Counter(v)
            mx = max(cnt.values())
            if cnt[v[2]] == mx and list(cnt.values()).count(mx) == 1:
                ans += 1
        return ans % MOD

