class Solution {
public:
    int subsequencesWithMiddleMode(vector<int>& nums) {
        const int MOD = 1e9 + 7; int n = nums.size(); long long ans = 0;
        int idx[5];
        function<void(int, int)> go = [&](int start, int d) {
            if (d == 5) {
                unordered_map<int,int> cnt;
                int v[5];
                for (int t = 0; t < 5; t++) { v[t] = nums[idx[t]]; cnt[v[t]]++; }
                int mx = 0;
                for (auto& p : cnt) mx = max(mx, p.second);
                if (cnt[v[2]] == mx) {
                    int reps = 0;
                    for (auto& p : cnt) if (p.second == mx) reps++;
                    if (reps == 1) ans++;
                }
                return;
            }
            for (int i = start; i < n; i++) { idx[d] = i; go(i + 1, d + 1); }
        };
        go(0, 0);
        return ans % MOD;
    }
};

