    let ans = 0;
    const go = (start, d, idx) => {
        if (d === 5) {
            const cnt = new Map(); const v = [];
            for (const t of idx) { v.push(nums[t]); cnt.set(nums[t], (cnt.get(nums[t]) || 0) + 1); }
            let mx = 0; for (const c of cnt.values()) mx = Math.max(mx, c);
