class Solution {
public:
    int subsequencesWithMiddleMode(vector<int>& nums) {
        const long long MOD = 1e9 + 7;
        int n = nums.size();
        unordered_map<int, long long> cntL, cntR;
        for (int x : nums) cntR[x]++;
        long long spl = 0, spr = 0, X = 0, Y1 = 0, Y2 = 0;
        auto C2 = [](long long x) { return x > 1 ? x * (x - 1) / 2 : 0LL; };
        auto upd = [&](int x, int dl, int dr) {
            long long a = cntL[x], b = cntR[x];
            spl -= C2(a); spr -= C2(b); X -= a * b; Y1 -= C2(a) * b; Y2 -= C2(b) * a;
            cntL[x] += dl; cntR[x] += dr;
            a = cntL[x]; b = cntR[x];
            spl += C2(a); spr += C2(b); X += a * b; Y1 += C2(a) * b; Y2 += C2(b) * a;
        };
        long long ans = 0;
        for (int j = 0; j < n; j++) {
            int v = nums[j];
            upd(v, 0, -1);
            long long cl = cntL[v], cr = cntR[v];
            long long Ln = j - cl, Rn = (n - 1 - j) - cr;
            long long fL = (C2(Rn) - spr) * Ln - X * Rn + Y1;
            long long fR = (C2(Ln) - spl) * Rn - X * Ln + Y2;
            long long res = (cl * fL + cr * fR + cl * cr * Ln * Rn
                   + C2(cl) * C2(Rn) + C2(cr) * C2(Ln)
                   + C2(cl) * cr * Rn + cl * C2(cr) * Ln
                   + C2(cl) * C2(cr)) % MOD;
            ans = (ans + res) % MOD;
            upd(v, 1, 0);
        }
        return (int)ans;
    }
};

