class Solution {
    public int subsequencesWithMiddleMode(int[] nums) {
        final long MOD = 1_000_000_007L;
        int n = nums.length;
        Map<Long, Long> cntL = new HashMap<>(), cntR = new HashMap<>();
        for (int x : nums) cntR.merge((long) x, 1L, Long::sum);
        long[] agg = new long[5]; // spl, spr, X, Y1, Y2
        java.util.function.BiConsumer<Long, long[]> upd = (key, dd) -> {};
        // helper as local method via arrays
        class H {
            long C2(long x) { return x > 1 ? x * (x - 1) / 2 : 0; }
            void upd(long x, long dl, long dr) {
                long a = cntL.getOrDefault(x, 0L), b = cntR.getOrDefault(x, 0L);
                agg[0] -= C2(a); agg[1] -= C2(b); agg[2] -= a * b; agg[3] -= C2(a) * b; agg[4] -= C2(b) * a;
                cntL.put(x, a + dl); cntR.put(x, b + dr);
                a = cntL.get(x); b = cntR.get(x);
                agg[0] += C2(a); agg[1] += C2(b); agg[2] += a * b; agg[3] += C2(a) * b; agg[4] += C2(b) * a;
            }
        }
        H h = new H();
        long ans = 0;
        for (int j = 0; j < n; j++) {
            long v = nums[j];
            h.upd(v, 0, -1);
            long cl = cntL.getOrDefault(v, 0L), cr = cntR.getOrDefault(v, 0L);
            long Ln = j - cl, Rn = (n - 1 - j) - cr;
            long fL = (h.C2(Rn) - agg[1]) * Ln - agg[2] * Rn + agg[3];
            long fR = (h.C2(Ln) - agg[0]) * Rn - agg[2] * Ln + agg[4];
            long res = (cl * fL + cr * fR + cl * cr * Ln * Rn
                   + h.C2(cl) * h.C2(Rn) + h.C2(cr) * h.C2(Ln)
                   + h.C2(cl) * cr * Rn + cl * h.C2(cr) * Ln
                   + h.C2(cl) * h.C2(cr)) % MOD;
            ans = (ans + res) % MOD;
            h.upd(v, 1, 0);
        }
        return (int) ans;
    }
}

